#include <iostream>
#include <vector>
#include <limits>
using namespace std;

void dijkstra(const vector<vector<int>>& graph, int start) {
    int n = graph.size();
    vector<int> dist(n, numeric_limits<int>::max());
    vector<bool> visited(n, false);
    dist[start] = 0;
    for (int count = 0; count < n-1; count++) {
        int minDist = numeric_limits<int>::max(), u = -1;
        for (int v = 0; v < n; v++)
            if (!visited[v] && dist[v] <= minDist) { minDist = dist[v]; u = v; }
        visited[u] = true;
        for (int v = 0; v < n; v++)
            if (!visited[v] && graph[u][v] && dist[u] != numeric_limits<int>::max() && dist[u] + graph[u][v] < dist[v])
                dist[v] = dist[u] + graph[u][v];
    }
    for (int i = 0; i < n; i++) cout << "Dist to " << i << ": " << dist[i] << endl;
}

int main() {
    vector<vector<int>> graph = {
        {0, 2, 0, 6, 0},
        {2, 0, 3, 8, 5},
        {0, 3, 0, 0, 7},
        {6, 8, 0, 0, 9},
        {0, 5, 7, 9, 0}
    };
    dijkstra(graph, 0);
    return 0;
}
